{
 "cited_positions": {
  "title": "Where You Need to Rank to Get Any Traffic from AIO/M",
  "columns": [
   "Position",
   "Cited",
   "Clicked",
   "Share of all citations"
  ],
  "rows": [
   {
    "label": "#1",
    "tip": "Example position:1.What the group contains:The first ordinary Google search result, regardless of citation order inside the AI answer.",
    "values": [
     "2.2%",
     "23.9%",
     "0.4%"
    ]
   },
   {
    "label": "#2-3",
    "tip": "Example position:3.What the group contains:Ordinary Google positions two and three.",
    "values": [
     "30.9%",
     "33.8%",
     "8.2%"
    ]
   },
   {
    "label": "#4-10",
    "tip": "Example position:7.What the group contains:Ordinary Google positions four through ten.",
    "values": [
     "24.7%",
     "43.2%",
     "73.2%"
    ]
   },
   {
    "label": "#11-20",
    "tip": "Example position:15.What the group contains:Ordinary Google positions eleven through twenty.",
    "values": [
     "6.1%",
     "17.0%",
     "13.6%"
    ]
   },
   {
    "label": "Positions 21+",
    "tip": "Example position:25.What the group contains:Ordinary Google position twenty-one or later.",
    "values": [
     "0.9%",
     "2.7%",
     "4.7%"
    ]
   }
  ]
 },
 "ai_answer_rates": {
  "title": "How often Google even shows an AI answer",
  "columns": [
   "Query type",
   "AI answer shown"
  ],
  "rows": [
   {
    "label": "No place name",
    "tip": "Example search:“seo coach”What the group contains:Searches containing neither a listed place name nor near me.",
    "values": [
     "68.7%"
    ]
   },
   {
    "label": "Contains a place name",
    "tip": "Example search:“seo coach chicago”What the group contains:Searches containing a listed state or major city.",
    "values": [
     "47.5%"
    ]
   },
   {
    "label": "\"near me\"",
    "tip": "Example search:“seo coach near me”What the group contains:Searches ending with near me.",
    "values": [
     "17.2%"
    ]
   }
  ]
 },
 "youtube_citations": {
  "title": "How often the AI answer cites a YouTube video",
  "columns": [
   "Kind of search",
   "Searches",
   "AI answer cites a YouTube video"
  ],
  "rows": [
   {
    "label": "How to / how do",
    "tip": "Searches starting with how to, how do, how does or how can. Example: how to fix a leaking tap.",
    "values": [
     "273",
     "71.4%"
    ]
   },
   {
    "label": "Comparison (vs)",
    "tip": "Searches containing vs or versus. Example: ahrefs vs semrush.",
    "values": [
     "100",
     "70.0%"
    ]
   },
   {
    "label": "Why",
    "tip": "Searches starting with why. Example: why is my tap leaking.",
    "values": [
     "31",
     "51.6%"
    ]
   },
   {
    "label": "What / who / when / where",
    "tip": "Searches starting with what, who, when, where or which. Example: what is a tap washer.",
    "values": [
     "462",
     "44.2%"
    ]
   },
   {
    "label": "Yes-or-no question",
    "tip": "Searches starting with is, are, can, does, do, should or will. Example: can I fix a tap myself.",
    "values": [
     "263",
     "44.1%"
    ]
   },
   {
    "label": "Best / top",
    "tip": "Searches containing best or top. Example: best tap repair kit.",
    "values": [
     "496",
     "38.7%"
    ]
   },
   {
    "label": "Other topic phrase",
    "tip": "Every other search. Example: tap washer replacement.",
    "values": [
     "6,565",
     "35.5%"
    ]
   },
   {
    "label": "How much / how many / how long",
    "tip": "Searches starting with how much, how many, how long, how far or how often. Example: how long does a tap washer last.",
    "values": [
     "210",
     "21.0%"
    ]
   },
   {
    "label": "Price / cost",
    "tip": "Searches containing price, cost or cheap. Example: plumber cost to fix tap.",
    "values": [
     "124",
     "10.5%"
    ]
   },
   {
    "label": "Near me",
    "tip": "Searches containing near me. Example: plumber near me.",
    "values": [
     "41",
     "0.0%"
    ]
   },
   {
    "label": "All searches",
    "tip": "8,565 searches that showed an AI Overview, collected July 30 to August 29, 2026, with 4,104 YouTube citations in total. YouTube received more AI Overview citations than any other website, ahead of Reddit (1,970), Facebook (855) and Wikipedia (519). Example: the AI Overview for how to fix a leaking tap links a YouTube video as one of its sources.",
    "values": [
     "8,565",
     "37.1%"
    ]
   }
  ]
 },
 "youtube_video_traits": {
  "title": "What the cited YouTube videos look like",
  "columns": [
   "The cited video",
   "Share of the 4,104 cited videos"
  ],
  "rows": [
   {
    "label": "Title contains at least half the search words",
    "tip": "Content words of the search, ignoring words such as how, the, best and for. Example: search fiber foods for constipation, video title Foods that Fight Constipation.",
    "values": [
     "65.6%"
    ]
   },
   {
    "label": "Title contains the main topic words",
    "tip": "Every content word of the search's main entity. Example: search high-protein foods, video title 5 CONVENIENT HIGH PROTEIN FOODS.",
    "values": [
     "48.4%"
    ]
   },
   {
    "label": "Also appears in the ordinary results for the same search",
    "tip": "The same video appears anywhere in the ordinary Google results collected for the search. Example: the video ranks 61st in the ordinary results.",
    "values": [
     "45.7%"
    ]
   },
   {
    "label": "Is a YouTube Short",
    "tip": "The cited address is a youtube.com/shorts link. Example: a 40-second vertical video.",
    "values": [
     "32.0%"
    ]
   },
   {
    "label": "Title contains every search word",
    "tip": "Every content word of the search is in the video title. Example: search catalytic converter cleaner, video title 6 Best Catalytic Converter Cleaners 2026.",
    "values": [
     "13.2%"
    ]
   },
   {
    "label": "Ranks in the ordinary top 10 for the same search",
    "tip": "The video sits in Google positions 1 through 10 of the ordinary results for the search. Example: the video ranks ninth.",
    "values": [
     "11.3%"
    ]
   }
  ]
 }
}
